<?php
session_start();require __DIR__.'/portal_lib.php';if(empty($_SESSION['ep_client'])){http_response_code(403);exit('Faça login no portal.');}$id=(string)($_GET['id']??'');$q=null;foreach(ep_read('orcamentos') as $x)if(($x['id']??'')===$id && ($x['client_id']??'')===($_SESSION['ep_client']??null) && ($x['status']??'')==='proposta_enviada'){$q=$x;break;}if(!$q){http_response_code(403);exit('Proposta indisponível.');}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Proposta ELEDS <?=ep_h($q['number']??'')?></title><?php ep_style();?><style>@media print{header,button{display:none}body{background:white}}</style></head><body><header>ELEDS — Proposta comercial</header><main><div class="panel"><h1>Proposta <?=ep_h($q['number']??'')?></h1><p>Cliente: <?=ep_h($q['customer']['name']??'')?></p><p>Data: <?=date('d/m/Y',strtotime($q['updated_at']??'now'))?></p><table><tr><th>Código / Produto</th><th>Qtd.</th><th>Unitário</th><th>Desc. (%)</th><th>Total</th></tr><?php foreach($q['items'] as $i):$d=max(0,min(100,(float)($i['discount']??0)));?><tr><td><?=ep_h($i['code']??'')?> — <?=ep_h($i['name']??'')?></td><td><?= (int)$i['qty']?></td><td><?=ep_money($i['price']??0)?></td><td><?=ep_h($d)?></td><td><?=ep_money((float)($i['price']??0)*(int)$i['qty']*(1-$d/100))?></td></tr><?php endforeach;?></table><p>Desconto geral adicional: <?=ep_h($q['discount']??0)?>%</p><h2>Total final: <?=ep_money(ep_total($q))?></h2><button onclick="window.print()">Imprimir / Salvar como PDF</button></div></main></body></html>
